/* =========================================================
   COPA MANAGER 2026 — datos/noticias-backs.js
   BACKS de las fotos de noticias (rectángulo 480x270). Aquí viven los fondos y
   sus composiciones; se irán agregando más backs con el tiempo.
     - newsPhotoTraining: campo de entrenamiento + entrenador (izq.) + logo (der.)
     - newsPhotoPresswall: fragmento del PRESS WALL con blur + entrenador
   Si no hay foto del entrenador se usa la SILUETA POR DEFECTO DEL JUEGO según su
   género (defaultPhotoFor → PERSON_DEFAULT / PERSON_DEFAULT_F), en el mismo lugar
   que la foto real. Cargar DESPUÉS de datos/presswall.js.
   ========================================================= */
const NEWS_BACK_FIELD = "data:image/jpeg;base64,";

// Silueta por defecto del JUEGO (la misma que se usa cuando un entrenador/jugador no tiene foto).
function _newsSilhouette(gender){
  try{ if(typeof defaultPhotoFor==="function"){ const d=defaultPhotoFor(gender); if(d) return d; } }catch(e){}
  try{
    const g=(typeof normLoose==="function")?normLoose(gender):String(gender||"").toLowerCase();
    if(g==="femenino" && typeof PERSON_DEFAULT_F!=="undefined" && PERSON_DEFAULT_F) return PERSON_DEFAULT_F;
    if(typeof PERSON_DEFAULT!=="undefined" && PERSON_DEFAULT) return PERSON_DEFAULT;
  }catch(e){}
  return "";
}
function _newsCoachImg(coachPhoto, objPos, gender){
  const src = coachPhoto || _newsSilhouette(gender);
  return `<img src="${src}" style="height:100%;width:auto;object-fit:contain;object-position:${objPos||'bottom center'};display:block;">`;
}
// BACK 1 — campo de entrenamiento: negro 15% + entrenador (izq.) + logo de la selección (der.).
function newsPhotoTraining(coachPhoto, teamLogo, widthPx, gender){
  const W=widthPx||480, k=W/480, H=270*k;
  const coach=_newsCoachImg(coachPhoto,'bottom left',gender);
  const logo = teamLogo ? `<img src="${teamLogo}" style="position:absolute;right:6%;top:50%;transform:translateY(-50%);height:62%;width:auto;object-fit:contain;filter:drop-shadow(0 3px 8px rgba(0,0,0,.45));">` : "";
  const inner = `<div style="position:relative;width:480px;height:270px;overflow:hidden;background:#1b3a1b url('${NEWS_BACK_FIELD}') center/cover;">`
    + `<div style="position:absolute;inset:0;background:rgba(0,0,0,0.15);"></div>`
    // El logo va ANTES de la persona en el DOM para que quede SIEMPRE DETRÁS de la imagen de
    // perfil (entrenador, jugador o árbitro), nunca encima.
    + logo
    + `<div style="position:absolute;left:3%;bottom:0;height:88%;display:flex;align-items:flex-end;">${coach}</div>`
    + `</div>`;
  return `<div style="width:${W}px;height:${H}px;overflow:hidden;border-radius:${Math.round(10*k)}px;"><div style="transform:scale(${k});transform-origin:top left;">${inner}</div></div>`;
}
// BACK 2 — press wall: fragmento del muro (centrado horizontal, bajado 25px, 120%) con blur(1) + entrenador.
function newsPhotoPresswall(coachPhoto, widthPx, gender){
  const W=widthPx||480, k=W/480, H=270*k;
  const Z=1.20, cy=0.61, down=25;
  const Wc=(480/0.746667)*Z, Hc=Wc*8006/8013;
  const left=240-0.5*Wc, top=135-cy*Hc+down;
  const bg = (typeof PRESSWALL_BG!=="undefined") ? PRESSWALL_BG : "";
  const tiles = (typeof pressWallTilesHTML==="function") ? pressWallTilesHTML() : "";
  const coach=_newsCoachImg(coachPhoto,'bottom center',gender);
  const inner = `<div style="position:relative;width:480px;height:270px;overflow:hidden;background:#0E1830;">`
    + `<div style="position:absolute;left:${left}px;top:${top}px;width:${Wc}px;height:${Hc}px;background:url('${bg}') center/cover;filter:blur(1px);">${tiles}</div>`
    + `<div style="position:absolute;left:50%;bottom:0;transform:translateX(-50%);height:88%;display:flex;align-items:flex-end;justify-content:center;">${coach}</div>`
    + `</div>`;
  return `<div style="width:${W}px;height:${H}px;overflow:hidden;border-radius:${Math.round(10*k)}px;"><div style="transform:scale(${k});transform-origin:top left;">${inner}</div></div>`;
}
